magic_t MagicInitContext(void)
{
    magic_t ctx;
    const char *filename = NULL;
    FILE *fd = NULL;

    ctx = magic_open(0);
    if (ctx == NULL) {
        SCLogError("magic_open failed: %s", magic_error(ctx));
        goto error;
    }

    (void)SCConfGet("magic-file", &filename);

    if (filename != NULL) {
        if (strlen(filename) == 0) {
            /* set filename to NULL on *nix systems so magic_load uses system
             * default path (see man libmagic) */
            SCLogConfig("using system default magic-file");
            filename = NULL;
        }
        else {
            SCLogConfig("using magic-file %s", filename);

            if ( (fd = fopen(filename, "r")) == NULL) {
                SCLogWarning("Error opening file: \"%s\": %s", filename, strerror(errno));
                goto error;
            }
            fclose(fd);
        }
    }

    if (magic_load(ctx, filename) != 0) {
        SCLogError("magic_load failed: %s", magic_error(ctx));
        goto error;
    }
    return ctx;

